import { GoogleGenerativeAI } from "@google/generative-ai";
import { NextResponse } from 'next/server';

// Initialize the Gemini SDK
// Make sure to set GEMINI_API_KEY in your .env.local file
const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY || "");

export async function POST(req: Request) {
  try {
    const { message } = await req.json();

    if (!process.env.GEMINI_API_KEY) {
      throw new Error("GEMINI_API_KEY is not configured.");
    }

    const model = genAI.getGenerativeModel({ 
      model: "gemini-2.5-flash",
      systemInstruction: `You are AuraHealth AI, a helpful medical assistant.
Do NOT give strict medical prescriptions.
Always suggest consulting a real doctor.
Give safe, general advice only.

You MUST respond strictly in the following JSON format:
{
  "causes": ["cause 1", "cause 2"],
  "remedies": ["remedy 1", "remedy 2"],
  "specialist": "Must be EXACTLY one of: General Physician, Cardiologist, Dermatologist, ENT Specialist, Pediatrician, Orthopedic, Gynecologist, Neurologist, Dentist, Psychiatrist",
  "disclaimer": "This is a simulated AI analysis, not a medical diagnosis. Please consult a doctor immediately if symptoms are severe."
}`
    });

    const result = await model.generateContent({
      contents: [{ role: "user", parts: [{ text: message }] }],
      generationConfig: { 
        responseMimeType: "application/json" 
      }
    });

    const reply = result.response.text();
    const jsonReply = reply ? JSON.parse(reply) : { error: "Failed to parse response" };

    return NextResponse.json(jsonReply);

  } catch (error: any) {
    console.error("Gemini Error:", error);
    return NextResponse.json({ error: error.message || "Failed to communicate with AI" }, { status: 500 });
  }
}

"use client";

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';

type Doctor = any; // Will use any for now as in JS, but could type this fully later
type Appointment = any;
type ToastMessage = { message: string; type: "success" | "error" } | null;

interface AppContextType {
  theme: 'light' | 'dark';
  setTheme: (theme: 'light' | 'dark') => void;
  activeVideoCall: Doctor | null;
  setActiveVideoCall: (doctor: Doctor | null) => void;
  appointments: Appointment[];
  setAppointments: (appointments: Appointment[]) => void;
  toast: ToastMessage;
  setToast: (toast: ToastMessage) => void;
  showToast: (message: string, type?: "success" | "error") => void;
  aiPreFillSymptoms: string;
  setAiPreFillSymptoms: (symptoms: string) => void;
  searchFilter: string;
  setSearchFilter: (filter: string) => void;
  handleCategoryClick: (category: string) => void;
  handleBookAppointment: (doctor: Doctor, slot: string, date: string, type: 'clinic'|'video') => void;
  startInstantCall: (doctor: Doctor) => void;
  endVideoCall: () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export function AppProvider({ children }: { children: ReactNode }) {
  const [theme, setThemeState] = useState<'light' | 'dark'>('light');
  const [activeVideoCall, setActiveVideoCall] = useState<Doctor | null>(null);
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [toast, setToast] = useState<ToastMessage>(null);
  const [aiPreFillSymptoms, setAiPreFillSymptoms] = useState('');
  const [searchFilter, setSearchFilter] = useState('All');

  // Handle Theme Toggle
  const setTheme = (newTheme: 'light' | 'dark') => {
    setThemeState(newTheme);
    if (newTheme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  };

  const showToast = (message: string, type: "success" | "error" = "success") => setToast({ message, type });

  const handleBookAppointment = (doctor: Doctor, slot: string, date: string, consultType: 'clinic'|'video') => {
    setAppointments([...appointments, { id: Date.now(), doctor, slot, date, type: consultType, status: 'Confirmed' }]);
    showToast(`${consultType === 'video' ? 'Video' : 'Clinic'} appointment confirmed!`);
  };

  const handleCategoryClick = (category: string) => {
    setSearchFilter(category);
    // Routing shift to search handled by the component using next/navigation push
  };

  const startInstantCall = (doctor: Doctor) => {
    setActiveVideoCall(doctor);
  };

  const endVideoCall = () => {
    setActiveVideoCall(null);
    showToast("Video consultation ended.", "success");
  };

  return (
    <AppContext.Provider value={{
      theme, setTheme,
      activeVideoCall, setActiveVideoCall,
      appointments, setAppointments,
      toast, setToast, showToast,
      aiPreFillSymptoms, setAiPreFillSymptoms,
      searchFilter, setSearchFilter,
      handleCategoryClick, handleBookAppointment,
      startInstantCall, endVideoCall
    }}>
      {children}
    </AppContext.Provider>
  );
}

export function useAppContext() {
  const context = useContext(AppContext);
  if (context === undefined) {
    throw new Error('useAppContext must be used within an AppProvider');
  }
  return context;
}

"use client";
import React, { useState } from 'react';
import { ChevronLeft, Star, MapPin, Video, Share2 } from 'lucide-react';
import { useAppContext } from '@/app/context/AppContext';
import { DOCTORS } from '@/lib/data';
import { useRouter, useParams } from 'next/navigation';

export default function DoctorProfilePage() {
  const router = useRouter();
  const params = useParams();
  const { handleBookAppointment, startInstantCall, showToast } = useAppContext();
  const [consultType, setConsultType] = useState<'clinic' | 'video'>('clinic');
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null);

  // In Next.js 15+, page params might be async in server components, but this is a client component
  // Resolving params.id via useParams
  const did = parseInt(params.id as string, 10);
  const selectedDoctor = DOCTORS.find(d => d.id === did);

  if (!selectedDoctor) {
    return (
      <div className="flex flex-col items-center justify-center p-12 text-center h-full">
        <h2 className="text-2xl font-bold dark:text-white">Doctor not found</h2>
        <button onClick={() => router.push('/')} className="mt-4 text-blue-600 font-bold hover:underline">Go Home</button>
      </div>
    );
  }

  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const dateStr = tomorrow.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });

  const handleShare = async () => {
    const url = window.location.href;
    if (navigator.share) {
      try {
        await navigator.share({
          title: `Book an appointment with ${selectedDoctor.name}`,
          text: `Check out ${selectedDoctor.name}, a great ${selectedDoctor.specialty} on AuraHealth!`,
          url: url,
        });
      } catch (err) {
        console.log("Error sharing", err);
      }
    } else {
      navigator.clipboard.writeText(url);
      showToast("Profile link copied to clipboard!", "success");
    }
  };

  return (
    <div className="absolute inset-0 bg-gray-50 dark:bg-gray-900 z-50 flex flex-col md:flex-row overflow-hidden animate-fade-in">

      {/* Left Column (Mobile: Header + Details) */}
      <div className="flex-1 overflow-y-auto w-full md:w-1/2 lg:w-3/5 border-r border-gray-200 dark:border-gray-800 relative pb-32 md:pb-0 h-full flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 md:p-6 bg-white dark:bg-gray-800 z-10 sticky top-0 shadow-sm md:shadow-none border-b border-gray-100 dark:border-gray-700">
          <button onClick={() => router.back()} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors">
            <ChevronLeft size={28} className="text-gray-700 dark:text-gray-300" />
          </button>
          <h2 className="font-bold text-gray-900 dark:text-white text-xl">Doctor Profile</h2>
          <button onClick={handleShare} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors">
            <Share2 size={24} className="text-gray-700 dark:text-gray-300" />
          </button>
        </div>

        {/* Profile Intro */}
        <div className="bg-blue-600 text-white p-8 md:p-10 text-center relative shadow-md">
          <div className="relative inline-block">
            <img src={selectedDoctor.image} alt={selectedDoctor.name} className="w-32 h-32 rounded-full border-[6px] border-white/20 shadow-2xl mx-auto mb-4 object-cover bg-gray-200" />
            {selectedDoctor.isOnlineNow && (
              <div className="absolute bottom-4 right-1 w-5 h-5 bg-green-400 border-[3px] border-white rounded-full animate-pulse" title="Online Now"></div>
            )}
          </div>
          <h1 className="text-3xl font-bold mb-1">{selectedDoctor.name}</h1>
          <p className="text-blue-100 font-medium text-lg">{selectedDoctor.specialty} • {selectedDoctor.qual}</p>

          <div className="flex justify-center gap-8 mt-8 bg-white/10 p-5 rounded-3xl backdrop-blur-sm max-w-md mx-auto">
            <div className="text-center flex-1 border-r border-white/20">
              <p className="text-2xl font-bold">{selectedDoctor.exp}</p>
              <p className="text-xs text-blue-100 uppercase tracking-wider font-bold mt-1">Experience</p>
            </div>
            <div className="text-center flex-1">
              <p className="text-2xl font-bold flex items-center justify-center gap-1.5"><Star size={20} className="fill-white" /> {selectedDoctor.rating}</p>
              <p className="text-xs text-blue-100 uppercase tracking-wider font-bold mt-1">{selectedDoctor.reviews} Reviews</p>
            </div>
          </div>
        </div>

        {/* Profile Content */}
        <div className="p-6 md:p-10 space-y-10">
          <div>
            <h3 className="font-bold text-gray-900 dark:text-white mb-3 text-xl">About Doctor</h3>
            <p className="text-gray-600 dark:text-gray-400 text-base leading-relaxed">{selectedDoctor.about}</p>
          </div>

          <div className="space-y-4">
            <div className="flex items-start gap-4 bg-white dark:bg-gray-800 p-5 rounded-2xl border border-gray-100 dark:border-gray-700 shadow-sm">
              <div className="bg-blue-100 dark:bg-blue-900/30 p-3 rounded-xl text-blue-600 dark:text-blue-500"><MapPin size={24} /></div>
              <div>
                <p className="font-bold text-gray-800 dark:text-white text-base">Clinic Location ({selectedDoctor.distance} km away)</p>
                <p className="text-gray-500 dark:text-gray-400 text-sm mt-1 leading-relaxed">{selectedDoctor.address}</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Right Column (Booking Area - Fixed on bottom for mobile, Sidebar on desktop) */}
      <div className="fixed bottom-0 left-0 right-0 md:static md:w-1/2 lg:w-2/5 md:h-full bg-white dark:bg-gray-800 border-t md:border-t-0 md:border-l border-gray-200 dark:border-gray-700 p-5 md:p-8 flex flex-col shadow-[0_-10px_30px_rgba(0,0,0,0.1)] md:shadow-none z-50">

        <div className="hidden md:block mb-8">
          <h3 className="font-bold text-gray-900 dark:text-white text-2xl">Book Appointment</h3>
        </div>

        {/* Toggle Type */}
        <div className="bg-gray-100 dark:bg-gray-900 p-1.5 rounded-2xl flex mb-6 shadow-inner shrink-0">
          <button
            onClick={() => { setConsultType('clinic'); setSelectedSlot(null); }}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-sm md:text-base font-bold transition-all ${consultType === 'clinic' ? 'bg-white dark:bg-gray-700 text-blue-700 dark:text-blue-400 shadow' : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'}`}
          >
            <MapPin size={18} /> In-Clinic Visit
          </button>
          <button
            onClick={() => { setConsultType('video'); setSelectedSlot(null); }}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-sm md:text-base font-bold transition-all ${consultType === 'video' ? 'bg-white dark:bg-gray-700 text-blue-700 dark:text-blue-400 shadow' : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'}`}
          >
            <Video size={18} /> Video Consult
          </button>
        </div>

        <div className="hidden md:flex flex-col gap-6 flex-1 overflow-y-auto pr-2">
          {/* Fee Summary */}
          <div className="flex items-center justify-between p-5 bg-gray-50 dark:bg-gray-900 rounded-2xl border border-gray-100 dark:border-gray-800">
            <div>
              <p className="font-bold text-gray-800 dark:text-gray-200">Consultation Fee</p>
              <p className="text-gray-500 dark:text-gray-400 text-sm">{consultType === 'clinic' ? 'Pay at clinic or online' : 'Pay securely online before call'}</p>
            </div>
            <div className="text-2xl font-black text-green-600 dark:text-green-500">₹{consultType === 'clinic' ? selectedDoctor.fee : selectedDoctor.videoFee}</div>
          </div>

          {/* Slots */}
          <div>
            <h3 className="font-bold text-gray-900 dark:text-white mb-4 flex items-center justify-between text-lg">
              Select Time <span className="text-sm font-bold text-blue-700 dark:text-blue-300 bg-blue-100 dark:bg-blue-900/50 px-3 py-1 rounded-full">{dateStr}</span>
            </h3>
            <div className="grid grid-cols-3 gap-3">
              {selectedDoctor.slots.map((slot: string) => (
                <button
                  key={slot}
                  onClick={() => setSelectedSlot(slot)}
                  className={`py-3.5 rounded-xl border-2 text-sm font-bold transition-all ${selectedSlot === slot
                      ? 'bg-blue-600 border-blue-600 text-white shadow-md transform scale-[1.02]'
                      : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 hover:border-blue-300 dark:hover:border-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/10'
                    }`}
                >
                  {slot}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Mobile quick view limits the slots */}
        <div className="md:hidden flex gap-3 mb-4 overflow-x-auto pb-2 scrollbar-hide">
             {selectedDoctor.slots.map((slot: string) => (
                <button
                  key={slot}
                  onClick={() => setSelectedSlot(slot)}
                  className={`py-2 px-6 rounded-lg border-2 text-sm font-bold whitespace-nowrap transition-all ${selectedSlot === slot
                      ? 'bg-blue-600 border-blue-600 text-white shadow-sm'
                      : 'bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300 border-gray-200 dark:border-gray-700'
                    }`}
                >
                  {slot}
                </button>
              ))}
        </div>

        <div className="flex flex-col gap-3 mt-auto shrink-0 pt-2 bg-white dark:bg-gray-800">
          {consultType === 'video' && selectedDoctor.isOnlineNow && (
            <button
              onClick={() => startInstantCall(selectedDoctor)}
              className="w-full bg-green-500 hover:bg-green-600 text-white py-3.5 md:py-4 rounded-2xl font-bold shadow-lg shadow-green-500/30 transition-colors flex items-center justify-center gap-2 animate-pulse text-base md:text-lg"
            >
              <Video size={20} /> Instant Video Consult Now - ₹{selectedDoctor.videoFee}
            </button>
          )}

          <div className="flex gap-4 items-center">
            <div className="md:hidden font-black text-2xl text-green-600 pl-2">₹{consultType === 'clinic' ? selectedDoctor.fee : selectedDoctor.videoFee}</div>

            <button
              onClick={() => {
                if (selectedSlot) {
                   handleBookAppointment(selectedDoctor, selectedSlot, dateStr, consultType);
                   router.push('/appointments');
                }
                else alert("Please select a time slot first.");
              }}
              className={`flex-1 text-white py-3.5 md:py-4 rounded-2xl font-bold transition-all text-base md:text-lg shadow-md ${selectedSlot ? 'bg-blue-600 hover:bg-blue-700 hover:shadow-xl hover:shadow-blue-600/20' : 'bg-gray-300 dark:bg-gray-700 text-gray-500 cursor-not-allowed shadow-none'
                }`}
            >
              Book {consultType === 'video' ? 'Video' : 'Clinic'} Slot
            </button>
          </div>
        </div>

      </div>
    </div>
  );
}

