export const BottomNav = () => {
  const { activeVideoCall } = useAppContext();
  const pathname = usePathname();

  // Hide nav on Doctor Profile or when Video Call is active
  if (activeVideoCall || pathname.startsWith('/doctor/')) return null;

  const NavItem = ({ icon, label, href }: any) => {
    const isActive = pathname === href;
    return (
      <Link
