"use client";
import React, { useState } from 'react';
import { Bot, Mic, Send, AlertTriangle, Stethoscope } from 'lucide-react';
import { useAppContext } from '@/app/context/AppContext';
import { DOCTORS } from '@/lib/data';
import { DoctorCard } from '../ui/DoctorCard';

export const AISymptomScreen = () => {
  const { aiPreFillSymptoms, handleCategoryClick } = useAppContext();
  const [symptoms, setSymptoms] = useState(aiPreFillSymptoms || '');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [error, setError] = useState('');
  const [isListening, setIsListening] = useState(false);

  const handleVoiceInput = () => {
    const SpeechRec = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRec) {
      setError("Voice input not supported in this browser. Please type.");
      return;
    }
    const recognition = new SpeechRec();
    recognition.lang = 'en-IN';
    recognition.interimResults = false;

    recognition.onstart = () => setIsListening(true);
    recognition.onerror = (e: any) => { setError("Voice input failed: " + e.error); setIsListening(false); };
    recognition.onresult = (e: any) => {
      setSymptoms(prev => prev + " " + e.results[0][0].transcript);
      setIsListening(false);
    };
    recognition.start();
  };

  const analyze = async () => {
    if (!symptoms.trim()) { setError("Please describe your symptoms first."); return; }
    setLoading(true); setError(''); setResult(null);

    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: symptoms }),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || "Failed to get AI analysis");
      }

      setResult(data);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An error occurred while connecting to Aura AI.");
    } finally { setLoading(false); }
  };

  return (
    <div className="flex flex-col h-full bg-gray-50 dark:bg-gray-900 pb-20 md:pb-0">
      <div className="bg-blue-600 dark:bg-blue-800 text-white p-6 pt-10 rounded-b-[2.5rem] shadow-md md:rounded-bl-[3rem] md:rounded-br-none">
        <h1 className="text-2xl font-bold flex items-center gap-3 max-w-4xl mx-auto"><Bot size={32} /> Aura AI Symptom Checker</h1>
        <p className="text-blue-100 mt-2 max-w-4xl mx-auto text-lg">Describe how you feel, or tap the mic to speak to our medical AI.</p>
      </div>

      <div className="flex-1 p-5 md:p-8 overflow-y-auto max-w-4xl mx-auto w-full">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700">
          <textarea
            value={symptoms}
            onChange={(e) => setSymptoms(e.target.value)}
            placeholder="e.g., I have a severe headache and mild fever since yesterday..."
            className="w-full h-32 p-4 border border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-900 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none resize-none text-gray-800 dark:text-white text-lg"
          />
          <div className="flex justify-between items-center mt-4">
